package com.thangit.boardinghouse.service;
import static org.assertj.core.api.Assertions.*;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.repository.*;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.service.ManagementReportService.Filter;
import com.thangit.boardinghouse.service.impl.AdminReportServiceImpl;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

@EnabledIfSystemProperty(named="reports.workspace.mysql",matches="true")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ManagementReportMysqlTest {
 final ManagementFinanceMysqlTest b=new ManagementFinanceMysqlTest();ManagementReportService reports;AdminReportServiceImpl files;
 @BeforeAll void setup()throws Exception{b.setup();var repo=new AdminReportRepository(b.f.db);reports=new ManagementReportService(b.f.db,repo);files=new AdminReportServiceImpl(repo);}
 @BeforeEach void fixture(){b.fixture();}
 Filter f(String type){return new Filter(type,b.a.property(),null,null,b.start,b.end,null,null,null,null,null,null,0,20);}
 Map<String,Object> read(String type){return reports.read(b.f.owner,f(type));}
 @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> data){return (List<Map<String,Object>>)data.get("rows");}
 Map<?,?> summary(Map<String,Object> data){return (Map<?,?>)data.get("summary");}
 BigDecimal n(Object v){return new BigDecimal(v.toString());}
 @Test void everyProjectionExecutesAgainstRealSchema(){for(String type:List.of("overview","operations","occupancy","revenue","payments","expenses","profit","debt","invoices","deposits","contracts","tenants","residences","bookings","utilities","services","maintenance","assets")){var data=read(type);assertThat(data).containsKeys("definitions","filteredTotals","rows","propertyIds");}}
 @Test void obligationsAreNotReceiptsOrDeposits(){long i=b.invoice();var invoice=read("revenue");assertThat(rows(invoice)).hasSize(1);assertThat(n(summary(invoice).get("periodInvoiceObligations"))).isEqualByComparingTo("3000000");assertThat(n(summary(invoice).get("cashIn"))).isZero();assertThat(rows(read("payments"))).isEmpty();assertThat(rows(read("invoices"))).hasSize(1);}
 @Test void payingOldDebtCountsInPaymentDateAndRemovesCurrentDebt(){long i=b.invoice();b.f.db.sql("UPDATE invoices SET billing_period=:period WHERE id=:id").param("period",b.start.minusMonths(1)).param("id",i).update();assertThat(rows(read("debt"))).hasSize(1);assertThat(rows(read("revenue"))).isEmpty();b.pay(i,"3000000",b.key());assertThat(rows(read("debt"))).isEmpty();assertThat(rows(read("payments"))).hasSize(1);assertThat(n(summary(read("overview")).get("cashIn"))).isEqualByComparingTo("3000000");}
 @Test void oldPaidAndCancelledInvoicesAreNotOutstanding(){long i=b.invoice();b.pay(i,"3000000",b.key());assertThat(rows(read("debt"))).isEmpty();assertThat(n(summary(read("overview")).get("outstandingDebt"))).isZero();}
 @Test void overdueDaysUseBusinessToday(){long i=b.invoice();b.f.db.sql("UPDATE invoices SET due_date=:due WHERE id=:id").param("due",LocalDate.now(InvoicePaymentRules.ZONE).minusDays(3)).param("id",i).update();var row=rows(read("debt")).getFirst();assertThat(((Number)row.get("overdue_days")).longValue()).isEqualTo(3);assertThat(row.get("status")).isEqualTo("OVERDUE");}
 void room(String status){b.f.insert("INSERT INTO rooms(property_id,code,monthly_rent,status) VALUES("+b.a.property()+",'"+b.key()+"',1000,'"+status+"')");}
 @Test void occupancyExcludesMaintenanceInactiveAndDoesNotCountReservedAsOccupied(){room("INACTIVE");room("MAINTENANCE");room("RESERVED");var s=summary(read("occupancy"));assertThat(n(s.get("availableRooms"))).isEqualByComparingTo("2");assertThat(n(s.get("occupiedRooms"))).isEqualByComparingTo("1");assertThat(n(s.get("occupancyRate"))).isEqualByComparingTo("50");var dashboard=new DashboardRepository(b.f.db).summary(1L,RoleCode.OWNER,b.a.property(),b.start,b.end.plusDays(1),b.start.minusMonths(1));assertThat(ReportKpis.occupancy(dashboard.get("occupiedRooms"),dashboard.get("availableRooms"))).isEqualByComparingTo(n(s.get("occupancyRate")));}
 void manager(boolean finance,boolean export){b.f.db.sql("INSERT IGNORE INTO property_managers(property_id,manager_id) VALUES(:property,2)").param("property",b.a.property()).update();for(String capability:List.of("FINANCE_READ","EXPORT")){if(capability.equals("FINANCE_READ")?!finance:!export)continue;b.f.db.sql("INSERT IGNORE INTO manager_property_capabilities(manager_id,property_id,capability,granted_by) VALUES(2,:property,:capability,1)").param("property",b.a.property()).param("capability",capability).update();}}
 @Test void managerWithoutFinanceStillSeesOperationsButNoMoney(){manager(false,false);var manager=new AuthenticatedUser(2L,"manager",RoleCode.MANAGER);b.invoice();var data=reports.read(manager,f("overview"));assertThat(rows(data)).hasSize(1);assertThat(rows(data).getFirst().get("cash_in")).isNull();assertThat(summary(data).containsKey("cashIn")).isFalse();assertThatThrownBy(()->reports.read(manager,f("debt"))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->reports.createExport(manager,f("occupancy"),"CSV")).isInstanceOf(RuntimeException.class);}
 @Test void tenantAndOtherOwnerCannotReadOrExport(){assertThatThrownBy(()->reports.read(b.f.tenant,f("overview"))).isInstanceOf(RuntimeException.class);var other=new AuthenticatedUser(2L,"other",RoleCode.OWNER);assertThatThrownBy(()->reports.createExport(other,f("debt"),"CSV")).isInstanceOf(RuntimeException.class);}
 @Test void technicianCannotAccessFinancialReports(){var tech=new AuthenticatedUser(6L,"tech",RoleCode.TECHNICIAN);assertThatThrownBy(()->reports.read(tech,f("overview"))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->reports.createExport(tech,new Filter("assets",null,null,null,b.start,b.end,null,null,null,null,null,null,0,20),"CSV")).isInstanceOf(RuntimeException.class);}
 @Test void inactiveHouseRetainsHistoricalReportAccess(){b.invoice();b.f.db.sql("UPDATE properties SET status='INACTIVE' WHERE id=:id").param("id",b.a.property()).update();assertThat(rows(read("revenue"))).hasSize(1);}
 @Test void companyFilterCannotExpandScope(){var filter=new Filter("overview",b.a.property(),999999L,null,b.start,b.end,null,null,null,null,null,null,0,20);assertThat(rows(reports.read(b.f.owner,filter))).isEmpty();}
 @Test void historyCountsPeopleSeparatelyFromResidenceVisits(){b.f.db.sql("INSERT INTO tenant_residences(tenant_profile_id,property_id,room_id,contract_id,residence_role,status,move_in_date,move_out_date,created_by) VALUES(:profile,:property,:room,:contract,'REPRESENTATIVE','MOVED_OUT',:start,:end,1)").param("profile",b.a.profile()).param("property",b.a.property()).param("room",b.a.room()).param("contract",b.a.contract()).param("start",b.start.minusDays(1)).param("end",b.start.plusDays(1)).update();assertThat(n(summary(read("tenants")).get("activePeople"))).isEqualByComparingTo("1");assertThat(rows(read("residences"))).hasSize(2);assertThat(rows(read("tenants"))).hasSize(1);for(var row:rows(read("residences")))assertThat(row).doesNotContainKeys("identity_number","phone","email","citizen_id");}
 @Test void draftAndApprovedVoucherAreNotCashOut(){long v=b.voucher("REPAIR");assertThat(rows(read("expenses"))).isEmpty();b.submit(v);b.approve(v);assertThat(rows(read("expenses"))).hasSize(1);assertThat(n(rows(read("expenses")).getFirst().get("paid_amount"))).isZero();assertThat(n(summary(read("profit")).get("cashOut"))).isZero();b.paid(v);assertThat(n(summary(read("profit")).get("cashOut"))).isEqualByComparingTo("2000000");}
 @Test void reversalRecomputesReportsWithoutDeletingSource(){long i=b.invoice();b.pay(i,"1000000",b.key());long p=b.f.db.sql("SELECT id FROM payments WHERE invoice_id=:id").param("id",i).query(Long.class).single();b.f.run(()->b.accounting.reversePayment(b.f.accountant,p,new com.thangit.boardinghouse.dto.request.accountant.AccountantRequests.Reason("Incorrect receipt",0)));assertThat(rows(read("payments"))).isEmpty();assertThat(n(summary(read("debt")).get("outstandingDebt"))).isEqualByComparingTo("3000000");assertThat(b.f.db.sql("SELECT COUNT(*) FROM payments WHERE id=:id").param("id",p).query(Long.class).single()).isOne();}
 @Test void filtersAndPaginationAreServerSide(){b.invoice();var data=reports.read(b.f.owner,new Filter("invoices",b.a.property(),null,null,b.start,b.end,"no-match",null,null,null,null,null,0,1));assertThat(rows(data)).isEmpty();assertThat(((Number)data.get("totalElements")).longValue()).isZero();var page=reports.read(b.f.owner,new Filter("invoices",b.a.property(),null,null,b.start,b.end,null,null,null,null,null,null,1,1));assertThat(rows(page)).isEmpty();assertThat(((Number)page.get("totalElements")).longValue()).isOne();}
 @Test void exportAllPagesUnicodeFormulaAndScopeHistory()throws Exception{b.f.db.sql("INSERT INTO other_income(property_id,income_code,category,amount,income_date,description,payment_method,created_by) WITH RECURSIVE seq AS (SELECT 1 n UNION ALL SELECT n+1 FROM seq WHERE n<800) SELECT :property,CONCAT('TC-',LPAD(n,4,'0')),'OTHER_INCOME',1,:date,'Actual separate collection','CASH',1 FROM seq").param("property",b.a.property()).param("date",b.start).update();var data=read("payments");assertThat(rows(data)).hasSize(20);assertThat(((Number)data.get("totalElements")).longValue()).isEqualTo(800);long start=System.nanoTime();var job=b.f.inTx(()->reports.createExport(b.f.owner,f("payments"),"XLSX"));String xml="";try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(files.download(b.f.owner,job.id())))){java.util.zip.ZipEntry part;while((part=zip.getNextEntry())!=null)if(part.getName().equals("xl/worksheets/sheet1.xml"))xml=new String(zip.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}assertThat(xml).contains("TC-0800","TC-0001","Báo cáo quản trị");long elapsed=(System.nanoTime()-start)/1_000_000;System.out.println("ReportExportRows=800;elapsedMs="+elapsed);assertThat(elapsed).isLessThan(30000);b.f.db.sql("UPDATE properties SET name='=2+3' WHERE id=:id").param("id",b.a.property()).update();var csv=b.f.inTx(()->reports.createExport(b.f.owner,f("payments"),"CSV"));assertThat(new String(files.download(b.f.owner,csv.id()),java.nio.charset.StandardCharsets.UTF_8)).contains("'=2+3");}
 @Test void exportIsBlockedAfterFinancialPermissionRevocation(){manager(true,true);b.invoice();var manager=new AuthenticatedUser(2L,"manager",RoleCode.MANAGER);var job=b.f.inTx(()->reports.createExport(manager,f("operations"),"CSV"));b.f.db.sql("DELETE FROM manager_property_capabilities WHERE manager_id=2 AND property_id=:id AND capability='FINANCE_READ'").param("id",b.a.property()).update();assertThatThrownBy(()->files.download(manager,job.id())).isInstanceOf(RuntimeException.class);}
 @Test void utilitiesUseConsumptionAndBillingPeriod(){var c=b.b.active("0",true);b.f.run(()->b.b.billing.record(b.f.owner,c.contract(),new MonthlyBillingService.Reading(b.start,0L,b.n("1380"),b.n("262"),"PHOTO","Actual readings",true)));var filter=new Filter("utilities",c.property(),null,null,b.start,b.end,null,null,null,null,null,null,0,20);var row=rows(reports.read(b.f.owner,filter)).getFirst();assertThat(n(row.get("electricity_kwh"))).isEqualByComparingTo("130");assertThat(n(row.get("water_m3"))).isEqualByComparingTo("12");assertThat(n(row.get("electricity_amount"))).isEqualByComparingTo("455000");}
 @Test void assetsDoNotInventDepreciation(){b.f.db.sql("INSERT INTO room_assets(room_id,name,quantity,condition_status) VALUES(:room,'Fan',2,'GOOD')").param("room",b.a.room()).update();assertThat(rows(read("assets")).getFirst().get("depreciated_value")).isNull();}
 @Test void invalidRangeAndUnsupportedFiltersDoNotSilentlyRun(){assertThatThrownBy(()->reports.read(b.f.owner,new Filter("overview",b.a.property(),null,null,b.end,b.start,null,null,null,null,null,null,0,20))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->reports.read(b.f.owner,new Filter("services",b.a.property(),null,null,b.start,b.end,null,null,null,123L,null,null,0,20))).isInstanceOf(RuntimeException.class);}
 @Test void serviceAmountsMatchIssuedSnapshotAndKeepUnits(){b.f.run(()->b.b.billing.service(b.f.owner,b.a.contract(),new MonthlyBillingService.ServiceRule("PARKING","Parking","QUANTITY","vehicle",b.n("50"),b.n("2"),b.start,null,false,"Agreed fee")));long id=b.invoice();var service=rows(read("services")).stream().filter(r->"Parking".equals(r.get("code"))).findFirst().orElseThrow();assertThat(service.get("unit")).isEqualTo("vehicle");assertThat(n(service.get("quantity"))).isEqualByComparingTo("2");assertThat(n(service.get("amount"))).isEqualByComparingTo(b.f.db.sql("SELECT SUM(amount) FROM invoice_items WHERE invoice_id=:id AND item_type='SERVICE'").param("id",id).query(BigDecimal.class).single());assertThat(service.get("collected_amount")).isNull();}
 @Test void expiringWindowIsFilterNotAutomaticCheckout(){b.f.db.sql("UPDATE contracts SET end_date=:end WHERE id=:id").param("end",LocalDate.now(InvoicePaymentRules.ZONE).plusDays(10)).param("id",b.a.contract()).update();var filter=new Filter("contracts",b.a.property(),null,null,b.start,b.end,null,"EXPIRING_WINDOW",null,null,null,null,0,20);assertThat(rows(reports.read(b.f.owner,filter))).hasSize(1);assertThat(b.f.db.sql("SELECT status FROM contracts WHERE id=:id").param("id",b.a.contract()).query(String.class).single()).isEqualTo("ACTIVE");}
 @Test void choiceListsCannotExposeOtherHouses(){assertThat((List<?>)reports.choices(b.f.owner,b.a.property()).get("rooms")).isNotEmpty();assertThatThrownBy(()->reports.choices(new AuthenticatedUser(2L,"other",RoleCode.OWNER),b.a.property())).isInstanceOf(RuntimeException.class);}
 @Test void maintenanceApprovalDoesNotInventActualCash(){long id=b.f.insert("INSERT INTO maintenance_requests(property_id,room_id,code,title,issue_type,priority,status,estimated_cost,actual_cost) VALUES("+b.a.property()+","+b.a.room()+",'"+b.key()+"','Repair','OTHER','NORMAL','NEW',100000,125000)");b.f.db.sql("INSERT INTO maintenance_costs(maintenance_request_id,total_cost,approval_status,proposed_by,approved_by) VALUES(:id,150000,'APPROVED',6,1)").param("id",id).update();b.f.db.sql("INSERT INTO maintenance_costs(maintenance_request_id,total_cost,approval_status,proposed_by,approved_by) VALUES(:id,180000,'APPROVED',6,1)").param("id",id).update();var row=rows(read("maintenance")).getFirst();assertThat(n(row.get("estimated_cost"))).isEqualByComparingTo("100000");assertThat(n(row.get("approved_cost"))).isEqualByComparingTo("180000");assertThat(row.get("paid_cost")).isNull();assertThat(n(summary(read("profit")).get("cashOut"))).isZero();}
 @Test void dashboardAndReportsShareFinancialKpisAndExcludeHeldDepositFromServiceCollections(){b.a=b.b.active("500000",false);long invoice=b.invoice();b.pay(invoice,"1000000",b.key());var data=summary(read("overview"));var dashboard=new DashboardRepository(b.f.db).summary(1L,RoleCode.OWNER,b.a.property(),b.start,b.end.plusDays(1),b.start.minusMonths(1));assertThat(n(dashboard.get("currentRevenue"))).isEqualByComparingTo(n(data.get("netServiceCollections")));assertThat(n(dashboard.get("debt"))).isEqualByComparingTo(n(data.get("outstandingDebt")));assertThat(n(data.get("cashIn"))).isEqualByComparingTo("1500000");assertThat(n(dashboard.get("currentRevenue"))).isEqualByComparingTo("1000000");}
 @Test void receiptRangeIncludesLastDayAndExcludesAdjacentMonths(){for(LocalDate date:List.of(b.start.minusDays(1),b.start,b.end,b.end.plusDays(1)))b.f.db.sql("INSERT INTO other_income(property_id,income_code,category,amount,income_date,description,payment_method,created_by) VALUES(:property,:code,'OTHER_INCOME',100,:date,'Date boundary fixture','CASH',1)").param("property",b.a.property()).param("code",b.key()).param("date",date).update();var data=read("payments");assertThat(rows(data)).hasSize(2);assertThat(n(summary(data).get("cashIn"))).isEqualByComparingTo("200");}
 @Test void draftCreatedInRangeIsVisibleEvenWhenTenancyStartsNextMonth(){var booking=b.f.booking("0");long id=b.f.contract(booking,"0");b.f.db.sql("UPDATE contracts SET status='DRAFT',start_date=:start,end_date=:end WHERE id=:id").param("id",id).param("start",b.start.plusMonths(1)).param("end",b.start.plusYears(1)).update();var filter=new Filter("contracts",booking.property(),null,null,b.start,b.end,null,"DRAFT",null,null,null,null,0,20);assertThat(rows(reports.read(b.f.owner,filter))).hasSize(1);}
}
